package com.myaaptha.domain.trust;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.myaaptha.platform.security.FieldEncryption;
import com.myaaptha.platform.state.EphemeralState;
import com.myaaptha.domain.social.SocialService;
import jakarta.validation.Valid;
import jakarta.validation.constraints.*;
import java.security.*;
import java.nio.charset.StandardCharsets;
import java.sql.Timestamp;
import java.time.*;
import java.util.*;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.transaction.support.TransactionTemplate;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/advisors/external")
public class ExternalFeedController {
 public record Connect(@Positive long advisorId,@NotBlank @Size(max=2048) String url,@AssertTrue boolean consent){}
 public record Source(long id,long advisorId,String title,String url,String lastSuccess,String error,boolean enabled){}
 public record SourcePage(List<Source> items,Long nextCursor){}
 public record SourceData(String title,String url){}
 public record Item(long id,long sourceId,String sourceName,String title,String summary,String url,String publishedAt,boolean saved,boolean liked){}
 public record Page(List<Item> items,Long nextCursor){}
 public record State(boolean enabled){}
 public record Flags(@NotNull Boolean saved,@NotNull Boolean liked){}
 public record Repost(@AssertTrue boolean confirm){}
 private record Reserved(long owner,long id,String url){}
 private final JdbcTemplate db;private final ObjectMapper json;private final FieldEncryption crypt;private final PublicFeedFetcher fetcher;private final TransactionTemplate tx;private final EphemeralState state;private final SocialService social;
 public ExternalFeedController(JdbcTemplate db,ObjectMapper json,FieldEncryption crypt,PublicFeedFetcher fetcher,org.springframework.transaction.PlatformTransactionManager manager,EphemeralState state,SocialService social){this.db=db;this.json=json;this.crypt=crypt;this.fetcher=fetcher;this.tx=new TransactionTemplate(manager);this.state=state;this.social=social;}
 @GetMapping("/sources") public SourcePage sources(Principal p,@RequestParam(defaultValue="0") long afterId){long owner=owner(p);if(afterId<0)throw bad("Invalid page");var rows=db.queryForList("SELECT * FROM advisor_external_sources WHERE user_id=? AND id>? ORDER BY id LIMIT 51",owner,afterId);return new SourcePage(rows.stream().limit(50).map(this::source).toList(),rows.size()>50?number(rows.get(49),"id"):null);}
 @PostMapping("/sources") public Source connect(Principal p,@Valid @RequestBody Connect input){long owner=owner(p);ownAdvisor(owner,input.advisorId());String url;try{url=PublicFeedFetcher.url(input.url()).toString();}catch(Exception e){throw bad(e.getMessage());}rate(owner);PublicFeedFetcher.Feed feed=fetch(url);long id=Objects.requireNonNull(tx.execute(status->{lock(owner);ownAdvisor(owner,input.advisorId());var existing=db.queryForList("SELECT id FROM advisor_external_sources WHERE user_id=? AND advisor_id=? AND url_hash=?",Long.class,owner,input.advisorId(),hash(url));if(!existing.isEmpty())return existing.getFirst();var key=new GeneratedKeyHolder();db.update(c->{var s=c.prepareStatement("INSERT INTO advisor_external_sources(user_id,advisor_id,url_hash,source_data,last_attempt) VALUES(?,?,?,?,CURRENT_TIMESTAMP)",new String[]{"id"});s.setLong(1,owner);s.setLong(2,input.advisorId());s.setString(3,hash(url));s.setString(4,encode(new SourceData(feed.title(),url)));return s;},key);return Objects.requireNonNull(key.getKey()).longValue();}));persist(owner,id,feed);return required(owner,id);}
 @PostMapping("/sources/{id}/refresh") public Source refresh(Principal p,@PathVariable long id){long owner=owner(p);Reserved reserved=reserve(owner,id,60);if(reserved==null)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"This feed was checked recently. Try again in a minute");refresh(reserved);return required(owner,id);}
 @PostMapping("/sources/{id}/state") public Source state(Principal p,@PathVariable long id,@RequestBody State state){long owner=owner(p);required(owner,id);db.update("UPDATE advisor_external_sources SET enabled=? WHERE user_id=? AND id=?",state.enabled(),owner,id);return required(owner,id);}
 @PostMapping("/sources/{id}/delete") public void remove(Principal p,@PathVariable long id){long owner=owner(p);required(owner,id);db.update("DELETE FROM advisor_external_sources WHERE user_id=? AND id=?",owner,id);}
 @GetMapping public Page items(Principal p,@RequestParam(defaultValue="ALL") String category,@RequestParam(defaultValue="false") boolean saved,@RequestParam(defaultValue="9223372036854775807") long beforeId){long owner=owner(p);if(category.length()>80||beforeId<1)throw bad("Invalid feed filter");String filter=category.equals("ALL")?"":" AND EXISTS(SELECT 1 FROM advisor_category_members m WHERE m.user_id=s.user_id AND m.advisor_id=s.advisor_id AND m.category_key=?)";List<Object> args=new ArrayList<>(List.of(owner,beforeId));if(!category.equals("ALL"))args.add(category);var rows=db.queryForList("SELECT i.*,s.source_data FROM advisor_external_items i JOIN advisor_external_sources s ON i.source_id=s.id AND i.user_id=s.user_id WHERE i.user_id=? AND i.id<?"+(saved?" AND i.saved=TRUE":"")+filter+" ORDER BY i.id DESC LIMIT 51",args.toArray());return new Page(rows.stream().limit(50).map(this::item).toList(),rows.size()>50?number(rows.get(49),"id"):null);}
 @PostMapping("/items/{id}") public Item flags(Principal p,@PathVariable long id,@Valid @RequestBody Flags flags){long owner=owner(p);if(db.update("UPDATE advisor_external_items SET saved=?,liked=? WHERE user_id=? AND id=?",flags.saved(),flags.liked(),owner,id)==0)throw missing();return requiredItem(owner,id);}
 @PostMapping("/items/{id}/repost") public com.myaaptha.domain.social.SocialDtos.Post repost(Principal p,@PathVariable long id,@Valid @RequestBody Repost confirm){long owner=owner(p);Item item=requiredItem(owner,id);return social.createPost(owner,item.title()+"\n"+item.url(),"PUBLIC",null,null);}
 @Scheduled(fixedDelayString="${myaaptha.external-feeds.refresh-ms:300000}",initialDelayString="${myaaptha.external-feeds.initial-delay-ms:60000}") public void refreshDue(){// Shared DB reservation prevents duplicate work across application replicas.
  var due=db.queryForList("SELECT s.id,s.user_id FROM advisor_external_sources s JOIN users u ON u.id=s.user_id WHERE u.account_status='ACTIVE' AND s.enabled=TRUE AND (s.last_attempt IS NULL OR s.last_attempt<?) ORDER BY s.last_attempt NULLS FIRST,s.id LIMIT 5",Timestamp.from(Instant.now().minusSeconds(1800)));for(var row:due){try{Reserved r=reserve(number(row,"user_id"),number(row,"id"),1800);if(r!=null)refresh(r);}catch(Exception ignored){/* A failed source does not stop other owners' feeds. */}}
 }
 private Reserved reserve(long owner,long id,int seconds){return tx.execute(status->{var rows=db.queryForList("SELECT * FROM advisor_external_sources WHERE user_id=? AND id=? FOR UPDATE",owner,id);if(rows.isEmpty())throw missing();var row=rows.getFirst();Instant at=instant(row.get("last_attempt"));if(at!=null&&at.isAfter(Instant.now().minusSeconds(seconds)))return null;db.update("UPDATE advisor_external_sources SET last_attempt=CURRENT_TIMESTAMP WHERE user_id=? AND id=?",owner,id);return new Reserved(owner,id,decode((String)row.get("source_data"),SourceData.class).url());});}
 private void refresh(Reserved reserved){try{rate(reserved.owner);var feed=fetch(reserved.url);persist(reserved.owner,reserved.id,feed);}catch(Exception e){db.update("UPDATE advisor_external_sources SET last_error=? WHERE user_id=? AND id=?","Feed unavailable. Check the public feed URL and try again later.",reserved.owner,reserved.id);if(e instanceof ResponseStatusException response)throw response;throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Feed unavailable. Check the public feed URL");}}
 private PublicFeedFetcher.Feed fetch(String url){try{return fetcher.fetch(url);}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Could not read this public RSS/Atom feed. Use its final HTTPS feed URL");}}
 private void persist(long owner,long source,PublicFeedFetcher.Feed feed){tx.executeWithoutResult(status->{var rows=db.queryForList("SELECT id FROM advisor_external_sources WHERE user_id=? AND id=? FOR UPDATE",Long.class,owner,source);if(rows.isEmpty())return;for(var item:feed.items().reversed()){String key=hash(item.url());if(db.queryForObject("SELECT COUNT(*) FROM advisor_external_items WHERE source_id=? AND item_key=?",Integer.class,source,key)==0)db.update("INSERT INTO advisor_external_items(user_id,source_id,item_key,item_data) VALUES(?,?,?,?)",owner,source,key,encode(item));else db.update("UPDATE advisor_external_items SET item_data=? WHERE user_id=? AND source_id=? AND item_key=?",encode(item),owner,source,key);}SourceData previous=decode((String)db.queryForObject("SELECT source_data FROM advisor_external_sources WHERE id=?",String.class,source),SourceData.class);db.update("UPDATE advisor_external_sources SET source_data=?,last_success=CURRENT_TIMESTAMP,last_error=NULL WHERE user_id=? AND id=?",encode(new SourceData(feed.title(),previous.url())),owner,source);});}
 private Source required(long owner,long id){var rows=db.queryForList("SELECT * FROM advisor_external_sources WHERE user_id=? AND id=?",owner,id);if(rows.isEmpty())throw missing();return source(rows.getFirst());}
 private Item requiredItem(long owner,long id){var rows=db.queryForList("SELECT i.*,s.source_data FROM advisor_external_items i JOIN advisor_external_sources s ON i.source_id=s.id WHERE i.user_id=? AND i.id=?",owner,id);if(rows.isEmpty())throw missing();return item(rows.getFirst());}
 private Source source(Map<String,Object> row){SourceData data=decode((String)row.get("source_data"),SourceData.class);Instant success=instant(row.get("last_success"));return new Source(number(row,"id"),number(row,"advisor_id"),data.title(),data.url(),success==null?null:success.toString(),(String)row.get("last_error"),Boolean.TRUE.equals(row.get("enabled")));}
 private Item item(Map<String,Object> row){var data=decode((String)row.get("item_data"),PublicFeedFetcher.Item.class);var source=decode((String)row.get("source_data"),SourceData.class);return new Item(number(row,"id"),number(row,"source_id"),source.title(),data.title(),data.summary(),data.url(),data.publishedAt(),Boolean.TRUE.equals(row.get("saved")),Boolean.TRUE.equals(row.get("liked")));}
 private void ownAdvisor(long owner,long id){if(db.queryForObject("SELECT COUNT(*) FROM advisor_people WHERE user_id=? AND id=?",Integer.class,owner,id)!=1)throw missing();}
 private void rate(long owner){try{if(state.increment("external-feed:user:"+owner,Duration.ofMinutes(1))>6||state.increment("external-feed:global",Duration.ofMinutes(1))>30)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Feed refresh limit reached. Try again shortly");}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Feed refresh is temporarily unavailable");}}
 private String encode(Object value){try{return crypt.encrypt(json.writeValueAsString(value));}catch(Exception e){throw new IllegalStateException("Could not save the private feed");}}
 private <T>T decode(String raw,Class<T> type){try{return json.readValue(crypt.decrypt(raw),type);}catch(Exception e){throw new IllegalStateException("Could not read the private feed");}}
 private void lock(long owner){db.queryForObject("SELECT id FROM users WHERE id=? FOR UPDATE",Long.class,owner);}
 private static long owner(Principal p){return Long.parseLong(p.getName());}private static long number(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}private static Instant instant(Object value){return value==null?null:value instanceof OffsetDateTime at?at.toInstant():((Timestamp)value).toInstant();}
 private static String hash(String value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
 private static ResponseStatusException bad(String s){return new ResponseStatusException(HttpStatus.BAD_REQUEST,s);}private static ResponseStatusException missing(){return new ResponseStatusException(HttpStatus.NOT_FOUND,"Feed or advisor not found");}
}
